namespace ghidra.lisa.pcode;



using ghidra.lisa.pcode.WorkItem;
using it.unive.lisa.program.cfg;
using it.unive.lisa.program.cfg.controlFlow;
using it.unive.lisa.program.cfg.edge;
using it.unive.lisa.program.cfg.statement;
using it.unive.lisa.util.datastructures.graph.code;

public class PcodeBranch : ControlFlowStructure {

	private Statement branch;
	private Statement fallThrough;

	protected PcodeBranch(NodeList<CFG, Statement, Edge> cfgMatrix, Statement condition) : base(cfgMatrix, condition, null)
    {
	}

	/* @Override */
	protected Collection<Statement> bodyStatements() {
		Collection<Statement> all = new(getTrueBranch());
		all.addAll(getFalseBranch());
		return all;
	}

	private Collection<Statement> getFalseBranch() {
		if (fallThrough == null) {
			return Set.of();
		}
		return new(cfgMatrix.followersOf(fallThrough));
	}

	private Collection<Statement> getTrueBranch() {
		if (branch == null) {
			return Set.of();
		}
		return new(cfgMatrix.followersOf(branch));
	}

	/* @Override */
	public bool contains(Statement st) {
		return bodyStatements().contains(st);
	}

	/* @Override */
	public void simplify() {
		// Nothing required here
	}

	/* @Override */
	public string toString() {
		return "if-then-else[" + getCondition() + "]";
	}

	/* @Override */
	public Collection<Statement> getTargetedStatements() {
		return bodyStatements();
	}

	public void addStatement(Statement st, PredType type) {
		if (type.equals(PredType.TRUE)) {
			branch = st;
		}
		else {
			fallThrough = st;
			setFirstFollower(st);
		}
	}

	public Statement getBranch() {
		return branch;
	}

	public Statement getFallThrough() {
		return fallThrough;
	}

}
